local M = {}

M.defaults = {
  keys = {
    start = "ga",
  },
  justify = "left", -- "left", "right", or "center"
}

M.config = vim.deepcopy(M.defaults)

local ns = vim.api.nvim_create_namespace("align_selection")

--- Highlight a buffer line range while waiting for user input
---@param bufnr integer
---@param start_line integer 1-indexed line
---@param end_line integer 1-indexed line
function M.highlight_range(bufnr, start_line, end_line)
  vim.api.nvim_buf_clear_namespace(bufnr, ns, 0, -1)
  local hl = vim.hl or vim.highlight
  local last_line = vim.api.nvim_buf_get_lines(bufnr, end_line - 1, end_line, false)[1] or ""
  hl.range(
    bufnr,
    ns,
    "Visual",
    { start_line - 1, 0 },
    { end_line - 1, #last_line },
    { regtype = "V", inclusive = true }
  )
  vim.cmd.redraw()
end

--- Clear selection highlight in buffer
---@param bufnr integer
function M.clear_highlight(bufnr)
  vim.api.nvim_buf_clear_namespace(bufnr, ns, 0, -1)
  vim.cmd.redraw()
end

--- Pad text according to display width and justification mode
---@param text string
---@param width integer
---@param justify? "left" | "right" | "center"
---@return string
function M.pad_cell(text, width, justify)
  -- Markdown table separator rows (e.g. `---`, `:---`, `:---:`, `---:`)
  local l_col, dashes, r_col = text:match("^(%:?)(%-+)(%:?)$")
  if dashes and #dashes > 0 then
    local pad_count = width - #l_col - #r_col
    if pad_count < 1 then
      pad_count = 1
    end
    return l_col .. string.rep("-", pad_count) .. r_col
  end

  local cur_len = vim.fn.strdisplaywidth(text)
  local diff = width - cur_len
  if diff <= 0 then
    return text
  end

  if justify == "right" then
    return string.rep(" ", diff) .. text
  elseif justify == "center" then
    local left_pad = math.floor(diff / 2)
    local right_pad = diff - left_pad
    return string.rep(" ", left_pad) .. text .. string.rep(" ", right_pad)
  else
    return text .. string.rep(" ", diff)
  end
end

--- Split a line by literal delimiter
---@param line string
---@param delim string
---@param split_all? boolean whether to split all occurrences or only the first
---@return string[]
function M.split_by_delim(line, delim, split_all)
  local parts = {}
  local p_delim = vim.pesc(delim)
  local start = 1

  while true do
    local s, e = line:find(p_delim, start)
    if not s then
      table.insert(parts, line:sub(start))
      break
    end
    table.insert(parts, line:sub(start, s - 1))
    start = e + 1
    if not split_all then
      table.insert(parts, line:sub(start))
      break
    end
  end
  return parts
end

--- Core alignment computation over an array of lines
---@param lines string[]
---@param opts? { delimiter?: string, justify?: "left" | "right" | "center", split?: "all" | "first", split_all?: boolean }
---@return string[]
function M.align_lines(lines, opts)
  opts = opts or {}
  local delim = opts.delimiter or "|"
  local justify = opts.justify or M.config.justify or "left"

  -- Delimiters like '|' and '&' default to splitting all columns (tables);
  -- others (like '-', '=', ':', '//') default to splitting only the first occurrence
  local split_all = opts.split_all
  if split_all == nil then
    if opts.split == "all" then
      split_all = true
    elseif opts.split == "first" or opts.split == "1" then
      split_all = false
    else
      split_all = (delim == "|" or delim == "&")
    end
  end

  local p_delim = vim.pesc(delim)
  local all_parts = {}
  local max_cols = 0
  local has_delim = false
  local min_indent = nil

  -- Collect parts for every line using numerical indexing (not ipairs)
  -- so that blank lines or lines without delimiter do not prematurely terminate iteration
  for i = 1, #lines do
    local line = lines[i]
    if line:find(p_delim) then
      has_delim = true
      local raw_parts = M.split_by_delim(line, delim, split_all)
      all_parts[i] = raw_parts
      if #raw_parts > max_cols then
        max_cols = #raw_parts
      end

      local indent_str = line:match("^(%s*)") or ""
      local indent_len = #indent_str
      if min_indent == nil or indent_len < min_indent then
        min_indent = indent_len
      end
    else
      all_parts[i] = nil
    end
  end

  if not has_delim or max_cols <= 1 then
    return lines
  end

  min_indent = min_indent or 0
  local base_indent = string.rep(" ", min_indent)

  -- Check if all matching lines start with delimiter (i.e. cell 1 has no non-whitespace text)
  local all_start_with_delim = true
  for i = 1, #lines do
    local parts = all_parts[i]
    if parts then
      if parts[1]:match("%S") then
        all_start_with_delim = false
        break
      end
    end
  end

  local trimmed_parts = {}
  for i = 1, #lines do
    local parts = all_parts[i]
    if parts then
      local row = {}
      for c = 1, #parts do
        local part = parts[c]
        if c == 1 then
          local content = part:match("^%s*(.-)%s*$") or ""
          row[c] = { text = content, is_first = true }
        elseif c == #parts and part:match("^%s*$") and split_all then
          row[c] = { text = "", is_trailing = true }
        else
          local content = part:match("^%s*(.-)%s*$") or ""
          row[c] = { text = content }
        end
      end
      trimmed_parts[i] = row
    end
  end

  local col_widths = {}
  for i = 1, #lines do
    local row = trimmed_parts[i]
    if row then
      for c = 1, #row do
        local cell = row[c]
        if not cell.is_trailing then
          local w = vim.fn.strdisplaywidth(cell.text)
          col_widths[c] = math.max(col_widths[c] or 0, w)
        end
      end
    end
  end

  local result = {}
  for i = 1, #lines do
    local row = trimmed_parts[i]
    if not row then
      table.insert(result, lines[i])
    else
      local buf = {}
      for c = 1, #row do
        local cell = row[c]
        if cell.is_trailing then
          -- Delimiter was already added after previous cell
        elseif c == 1 then
          if all_start_with_delim then
            -- When all lines start with delimiter (tables or bullet lists), align cleanly at base_indent
            table.insert(buf, base_indent)
          else
            local padded = M.pad_cell(cell.text, col_widths[c], justify)
            table.insert(buf, base_indent .. padded)
            if c < #row and not (c == #row - 1 and row[#row].is_trailing) then
              table.insert(buf, " ")
            end
          end
        elseif c == #row and not row[#row].is_trailing then
          -- Last column when there is no trailing delimiter: avoid extra trailing spaces
          table.insert(buf, " " .. cell.text)
        else
          local padded = M.pad_cell(cell.text, col_widths[c], justify)
          table.insert(buf, " " .. padded)
          if c < #row and not (c == #row - 1 and row[#row].is_trailing) then
            table.insert(buf, " ")
          elseif c < #row and row[#row].is_trailing then
            table.insert(buf, " ")
          end
        end

        if c < #row then
          table.insert(buf, delim)
        end
      end
      table.insert(result, table.concat(buf, ""))
    end
  end

  return result
end

--- Apply character-level inline diff for a single line using nvim_buf_set_text
--- Ensures highlight-undo.nvim only highlights exact whitespace additions/changes
---@param bufnr integer
---@param row integer 0-indexed line number
---@param s1 string original line content
---@param s2 string updated line content
function M.apply_line_diff(bufnr, row, s1, s2)
  if s1 == s2 then
    return
  end

  local b1, b2 = {}, {}
  for i = 1, #s1 do
    table.insert(b1, s1:sub(i, i))
  end
  for i = 1, #s2 do
    table.insert(b2, s2:sub(i, i))
  end

  local t1 = table.concat(b1, "\n") .. "\n"
  local t2 = table.concat(b2, "\n") .. "\n"
  local hunks = vim.diff(t1, t2, { result_type = "indices" })
  if not hunks or #hunks == 0 then
    return
  end

  -- Apply byte hunks in reverse order (right-to-left) so column offsets don't shift
  for i = #hunks, 1, -1 do
    local hunk = hunks[i]
    local start_a, count_a, start_b, count_b = hunk[1], hunk[2], hunk[3], hunk[4]
    local col_start = count_a > 0 and (start_a - 1) or start_a
    local col_end = col_start + count_a
    local replacement = count_b > 0 and s2:sub(start_b, start_b + count_b - 1) or ""

    vim.api.nvim_buf_set_text(bufnr, row, col_start, row, col_end, { replacement })
  end
end

--- Apply minimal diff edits to buffer
---@param bufnr integer
---@param base_line integer 0-indexed start line
---@param old_lines string[]
---@param new_lines string[]
---@return boolean Whether changes were applied
function M.apply_diff(bufnr, base_line, old_lines, new_lines)
  local any_changed = false
  for offset = 0, #old_lines - 1 do
    local s1 = old_lines[offset + 1]
    local s2 = new_lines[offset + 1]
    if s1 ~= s2 then
      M.apply_line_diff(bufnr, base_line + offset, s1, s2)
      any_changed = true
    end
  end
  return any_changed
end

--- Expand single line to contiguous lines containing the delimiter
---@param bufnr integer
---@param line integer 1-indexed line
---@param delim string
---@return integer start_line, integer end_line (1-indexed)
function M.expand_range(bufnr, line, delim)
  local total_lines = vim.api.nvim_buf_line_count(bufnr)
  local p_delim = vim.pesc(delim)
  local start_l = line
  local end_l = line

  local cur_line = vim.api.nvim_buf_get_lines(bufnr, line - 1, line, false)[1] or ""
  if not cur_line:find(p_delim) then
    return line, line
  end

  while start_l > 1 do
    local prev = vim.api.nvim_buf_get_lines(bufnr, start_l - 2, start_l - 1, false)[1] or ""
    if prev:find(p_delim) and not prev:match("^%s*$") then
      start_l = start_l - 1
    else
      break
    end
  end

  while end_l < total_lines do
    local next_l = vim.api.nvim_buf_get_lines(bufnr, end_l, end_l + 1, false)[1] or ""
    if next_l:find(p_delim) and not next_l:match("^%s*$") then
      end_l = end_l + 1
    else
      break
    end
  end

  return start_l, end_l
end

--- Align line range in buffer
---@param bufnr integer
---@param start_line integer 1-indexed line
---@param end_line integer 1-indexed line
---@param opts? { delimiter?: string, justify?: "left" | "right" | "center", split?: "all" | "first" }
---@return boolean Whether buffer was modified
function M.align_range(bufnr, start_line, end_line, opts)
  bufnr = bufnr == 0 and vim.api.nvim_get_current_buf() or bufnr
  opts = opts or {}

  if not opts.delimiter or opts.delimiter == "" then
    return false
  end

  -- If single line, try expanding to contiguous block containing delimiter
  if start_line == end_line then
    start_line, end_line = M.expand_range(bufnr, start_line, opts.delimiter)
  end

  local old_lines = vim.api.nvim_buf_get_lines(bufnr, start_line - 1, end_line, false)
  if #old_lines == 0 then
    return false
  end

  local new_lines = M.align_lines(old_lines, opts)
  return M.apply_diff(bufnr, start_line - 1, old_lines, new_lines)
end

--- Parse command/input arguments: e.g. `|`, `| right`, `delimiter=-`, `split=all`
---@param args_str? string
---@return { delimiter?: string, justify?: "left" | "right" | "center", split?: "all" | "first" }
function M.parse_args(args_str)
  if not args_str or args_str:match("^%s*$") then
    return {}
  end

  local opts = {}
  -- Check for key=value syntax
  if args_str:find("=") and (args_str:find("delimiter=") or args_str:find("justify=") or args_str:find("split=")) then
    for part in args_str:gmatch("%S+") do
      local k, v = part:match("^(%w+)=(.*)$")
      if k and v then
        if k == "delimiter" or k == "delim" or k == "d" then
          opts.delimiter = v
        elseif k == "justify" or k == "j" then
          local j = v:lower()
          if j == "right" or j == "center" or j == "left" then
            opts.justify = j
          end
        elseif k == "split" or k == "s" then
          local s = v:lower()
          if s == "all" or s == "first" or s == "1" then
            opts.split = s
          end
        end
      end
    end
    return opts
  end

  -- Positional tokens: [delim] [justify] [split]
  local tokens = {}
  for tok in args_str:gmatch("%S+") do
    table.insert(tokens, tok)
  end

  if #tokens == 1 then
    opts.delimiter = tokens[1]
  elseif #tokens >= 2 then
    opts.delimiter = tokens[1]
    for i = 2, #tokens do
      local t = tokens[i]:lower()
      if t == "right" or t == "r" then
        opts.justify = "right"
      elseif t == "center" or t == "c" then
        opts.justify = "center"
      elseif t == "left" or t == "l" then
        opts.justify = "left"
      elseif t == "all" or t == "first" or t == "1" then
        opts.split = t
      end
    end
  end

  return opts
end

--- Prompt user for delimiter and align the range, highlighting the selection while waiting
---@param bufnr integer
---@param start_line integer
---@param end_line integer
---@param base_opts? table
function M.prompt_and_align(bufnr, start_line, end_line, base_opts)
  -- Highlight the target range while the prompt is active
  M.highlight_range(bufnr, start_line, end_line)

  vim.ui.input({ prompt = "Align delimiter: " }, function(input)
    -- Clear highlight as soon as the prompt is submitted or dismissed
    M.clear_highlight(bufnr)

    if not input or input:match("^%s*$") then
      return
    end

    local parsed = M.parse_args(input)
    local merged = vim.tbl_extend("force", base_opts or {}, parsed)
    if not merged.delimiter or merged.delimiter == "" then
      return
    end

    M.align_range(bufnr, start_line, end_line, merged)
  end)
end

--- Operatorfunc handler for normal mode operator-pending alignment
---@param _type string motion type
function M.operator(_type)
  local bufnr = vim.api.nvim_get_current_buf()
  local start_mark = vim.api.nvim_buf_get_mark(bufnr, "[")
  local end_mark = vim.api.nvim_buf_get_mark(bufnr, "]")
  local start_line = start_mark[1]
  local end_line = end_mark[1]

  if start_line == 0 or end_line == 0 then
    return
  end
  if start_line > end_line then
    start_line, end_line = end_line, start_line
  end

  M.prompt_and_align(bufnr, start_line, end_line)
end

--- Trigger for operator-pending mapping
---@return string "g@"
function M.operator_trigger()
  vim.go.operatorfunc = "v:lua.require'utils.align'.operator"
  return "g@"
end

--- Visual mode alignment handler
function M.align_visual()
  -- Exit visual mode cleanly to set '< and '> marks
  local esc = vim.api.nvim_replace_termcodes("<Esc>", true, false, true)
  vim.api.nvim_feedkeys(esc, "nx", false)

  local bufnr = vim.api.nvim_get_current_buf()
  local start_line = vim.api.nvim_buf_get_mark(bufnr, "<")[1]
  local end_line = vim.api.nvim_buf_get_mark(bufnr, ">")[1]

  if start_line == 0 or end_line == 0 then
    return
  end
  if start_line > end_line then
    start_line, end_line = end_line, start_line
  end

  M.prompt_and_align(bufnr, start_line, end_line)
end

--- Autocompletion handler for :Align command
---@param arg_lead string
---@param cmd_line string
---@param cursor_pos integer
---@return string[]
function M.complete(arg_lead, cmd_line, cursor_pos)
  local parts = vim.split(cmd_line:sub(1, cursor_pos), "%s+", { trimempty = false })
  if #parts == 2 then
    local candidates = { "|", "=", ":", ",", "//", "-", "delimiter=", "justify=", "split=" }
    local matches = {}
    for _, c in ipairs(candidates) do
      if vim.startswith(c, arg_lead) then
        table.insert(matches, c)
      end
    end
    return matches
  elseif #parts >= 3 then
    local candidates = {
      "left",
      "right",
      "center",
      "all",
      "first",
      "justify=left",
      "justify=right",
      "justify=center",
      "split=all",
      "split=first",
    }
    local matches = {}
    for _, c in ipairs(candidates) do
      if vim.startswith(c, arg_lead) then
        table.insert(matches, c)
      end
    end
    return matches
  end
  return {}
end

--- Setup alignment module, keymaps, and commands
---@param opts? { keys?: { start?: string }|string, justify?: "left" | "right" | "center" }
function M.setup(opts)
  M.config = vim.tbl_deep_extend("force", M.defaults, opts or {})

  -- Create :Align command
  vim.api.nvim_create_user_command("Align", function(cmd_opts)
    local bufnr = vim.api.nvim_get_current_buf()
    local parsed = M.parse_args(cmd_opts.args)
    local start_line = cmd_opts.line1
    local end_line = cmd_opts.line2

    if parsed.delimiter and parsed.delimiter ~= "" then
      M.align_range(bufnr, start_line, end_line, parsed)
    else
      M.prompt_and_align(bufnr, start_line, end_line, parsed)
    end
  end, {
    range = true,
    nargs = "*",
    complete = M.complete,
    desc = "Align text by delimiter with optional justification",
  })

  -- Set default keys
  local start_key
  if type(M.config.keys) == "string" then
    start_key = M.config.keys
  elseif type(M.config.keys) == "table" then
    start_key = M.config.keys.start
  end

  if start_key then
    -- Normal mode operator-pending mapping (e.g. `gaip`, `ga2j`, `ga_`)
    vim.keymap.set("n", start_key, M.operator_trigger, {
      expr = true,
      desc = "Align (operator-pending)",
    })

    -- Visual mode mapping (e.g. select lines and press `ga`)
    vim.keymap.set("x", start_key, M.align_visual, {
      desc = "Align visual selection",
    })
  end
end

return M
